SourceCode.Declaration:
/// <summary>
/// Extension of postJournal control on InventJournalCount form.
/// </summary>
[ExtensionOf(formControlStr(InventJournalCount, postJournal))]
final class METInventJournalCountPostButton_Extension
{
}

Method.Source:
/// <summary>
/// Validate restricted warehouses on journal lines before posting
/// </summary>
public void clicked()
{
    FormRun             formRun = this.formRun();
    FormDataSource      inventJournalTable_ds = formRun.dataSource(formDataSourceStr(InventJournalCount, InventJournalTable));
    InventJournalTable  inventJournalTable = inventJournalTable_ds.cursor();
    boolean             hasRestricted = false;

    if (inventJournalTable && !Global::isSystemAdministrator())
    {
        InventJournalTrans              journalTrans;
        InventDim                       inventDim;
        METUserSecurityGroupList        securityGroupList;
        METUserSecurityWarehouseList    warehouseList;

        select firstonly RecId from journalTrans
            where journalTrans.JournalId == inventJournalTable.JournalId
            join inventDim
                where inventDim.inventDimId == journalTrans.inventDimId
            join warehouseList
                where warehouseList.InventLocationId == inventDim.InventLocationId
                   && warehouseList.Company == journalTrans.dataAreaId
                   && warehouseList.RestrictCountingJournal == NoYes::Yes
            exists join securityGroupList
                where securityGroupList.UserSecurityGroupId == warehouseList.UserSecurityGroupId
                   && securityGroupList.UserId == curUserId();

        if (journalTrans.RecId)
        {
            hasRestricted = true;
        }
    }

    if (hasRestricted)
    {
        throw error("@MET:InventJournalCountingWarehouseRestrictedPost");
    }

    next clicked();
}
